//! the reproducible guest control-channel agent (Fable §2): a static musl
//! binary, compiled FROM SOURCE inside the pinned builder container — never on
//! the host (rustc drift would change the `.tdvmm` bytes) and never downloaded
//! (owner ruling: the agent runs privileged in the guest, so nothing
//! precompiled is trusted). The source travels EMBEDDED in the tdvmm binary —
//! exactly the set `agent_src_id` hashes, generated by the root build.rs — so
//! the binary and its agent source can never be version-skewed. Each build
//! materializes the set into a scratch context, builds reproducibly, and
//! caches the result under `<cache>/agent/` keyed by everything that shapes
//! the bytes.

use std::path::{Path, PathBuf};

use crate::artifact;
use crate::engine;
use crate::ui;
use super::cache::resolve_cache_dir;
use super::pins::agent_builder_pin;
use super::util::{now_nanos, sha256_file_hex, ScratchDir};
use super::ux::{run_build, Ux};
use super::{BuildAgentArgs, BUILD_EPOCH};

include!(concat!(env!("OUT_DIR"), "/agent_src.rs"));

/// The root workspace manifest, embedded VERBATIM as a materialize-only build
/// input: it carries `[workspace]` and `[profile.agent-release]`, which shape
/// the agent bytes. Deliberately NOT part of [`agent_src_id`] (unchanged
/// construction); instead its sha is folded into [`agent_build_key`], and the
/// build always uses THIS manifest — a checkout's local profile edit can no
/// longer silently change the agent.
const ROOT_MANIFEST: &str = include_str!("../../Cargo.toml");

/// RUSTFLAGS for the reproducible container build. rust-lld consumes link args
/// directly (no `cc` driver), so `--build-id=none` is passed as-is. The remaps
/// stabilize the two absolute paths that would otherwise leak into the bytes:
/// the /src source mount and CARGO_HOME. Set as an ENV var, which takes
/// precedence over any config-file rustflags.
const AGENT_RUSTFLAGS: &str = "-C linker=rust-lld -C link-self-contained=yes -C link-arg=--build-id=none \
                     --remap-path-prefix=/src=/tdvmm --remap-path-prefix=/work/cargo=/cargo";

/// The in-container build script (over the materialized source at /src).
const AGENT_BUILD_SCRIPT: &str = "set -e; cd /src && \
        cargo build -p tdvmm-agent --profile agent-release \
            --target x86_64-unknown-linux-musl --locked && \
        cp /work/target/x86_64-unknown-linux-musl/agent-release/tdvmm-agent /work/tdvmm-agent";

/// A deterministic identity of the agent's SOURCES — the embedded `tdvmm-agent`
/// and `tdvmm-proto` trees plus the root `Cargo.lock` (exactly [`AGENT_SRC`]).
/// Compiled into the agent as its build hash (`TDVMM_AGENT_BUILD`, the
/// compatibility oracle reported by `ping`/hello) and folded into the bake
/// cache key. First 16 hex of the sha256.
///
/// Same construction as the retired checkout hash (per-tree `tree_hash` +
/// `Cargo.lock` sha), computed from the EMBEDDED table — so the value is
/// unchanged, checkout-independent, and infallible. The
/// `embedded_agent_source_matches_checkout` tripwire test keeps the table
/// equal to the checkout. `images.lock` is deliberately INSIDE the hashed
/// tree: a builder bump is a real toolchain change.
pub(super) fn agent_src_id() -> String {
    let a = embedded_tree_hash("tdvmm-agent/");
    let p = embedded_tree_hash("tdvmm-proto/");
    let lock = artifact::sha256_hex(embedded_file("Cargo.lock"));
    artifact::sha256_hex(format!("{a}\n{p}\n{lock}\n").as_bytes())[..16].to_string()
}

/// One embedded file's bytes. The table is build.rs-generated from the repo,
/// so a missing entry is a generator bug, not a runtime condition.
fn embedded_file(rel: &str) -> &'static [u8] {
    AGENT_SRC
        .iter()
        .find(|(path, _)| *path == rel)
        .map(|(_, bytes)| *bytes)
        .unwrap_or_else(|| panic!("embedded agent source table is missing {rel}"))
}

/// [`super::fsops::tree_hash`] over the embedded table's `prefix` subtree:
/// same construction (`<relpath>\0<sha256(content)>\n`, relpath-sorted), so
/// the value equals hashing the checkout tree. The table is sorted by full
/// relpath, which orders a shared-prefix subtree by its stripped relpath too.
fn embedded_tree_hash(prefix: &str) -> String {
    let mut buf = String::new();
    for (path, bytes) in AGENT_SRC {
        if let Some(rel) = path.strip_prefix(prefix) {
            buf.push_str(rel);
            buf.push('\0');
            buf.push_str(&artifact::sha256_hex(bytes));
            buf.push('\n');
        }
    }
    artifact::sha256_hex(buf.as_bytes())
}

/// The built-agent artifact cache key: covers EVERYTHING that shapes the
/// agent's bytes — the embedded source set (incl. images.lock = the builder
/// digest), the root manifest (profile + workspace shape), the build flags +
/// script, and the epoch. There is no recorded pin anymore, so a cached binary
/// may only be reused when this whole key matches; a profile edit, flag
/// change, or builder bump each miss and rebuild. First 16 hex.
fn agent_build_key() -> String {
    let manifest = artifact::sha256_hex(ROOT_MANIFEST.as_bytes());
    let flags = artifact::sha256_hex(AGENT_RUSTFLAGS.as_bytes());
    let script = artifact::sha256_hex(AGENT_BUILD_SCRIPT.as_bytes());
    artifact::sha256_hex(
        format!(
            "tdvmm-agent-build v1\n{}\n{manifest}\n{flags}\n{script}\n{BUILD_EPOCH}\n",
            agent_src_id()
        )
        .as_bytes(),
    )[..16]
        .to_string()
}

/// Materialize the embedded source set into `dst` as the container build
/// context: the hashed table verbatim, plus the two materialize-only inputs —
/// the root manifest and a stub root `src/main.rs` (cargo refuses to load a
/// workspace whose root `[[bin]]` target file is missing; the root package is
/// never compiled, so the stub affects nothing).
fn materialize_agent_src(dst: &Path) -> std::io::Result<()> {
    for (rel, bytes) in AGENT_SRC {
        let path = dst.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&path, bytes)?;
    }
    std::fs::write(dst.join("Cargo.toml"), ROOT_MANIFEST)?;
    std::fs::create_dir_all(dst.join("src"))?;
    std::fs::write(dst.join("src/main.rs"), "fn main() {}\n")?;
    Ok(())
}

/// Ensure the guest agent binary is available, mirroring `ensure_kernel`: the
/// sidecar-verified copy in `<cache>/agent/` keyed by [`agent_build_key`],
/// else the reproducible container build from the EMBEDDED source, published
/// into the cache. No checkout, no download — the only failure mode left is
/// the build itself. Returns the binary path + its embedded build hash.
pub(super) fn ensure_agent(
    cache_dir: &Path,
    ux: &Ux,
) -> Result<(PathBuf, String), Box<dyn std::error::Error>> {
    let build_hash = agent_src_id();
    let key = agent_build_key();
    let agent_dir = cache_dir.join("agent");
    let cached = agent_dir.join(format!("tdvmm-agent-{key}"));
    let sidecar = agent_dir.join(format!("tdvmm-agent-{key}.sha256"));
    if cached.is_file() {
        let want = std::fs::read_to_string(&sidecar).map(|s| s.trim().to_string()).unwrap_or_default();
        match sha256_file_hex(&cached) {
            Ok(got) if !want.is_empty() && got == want => {
                ux.progress.note("cached (sha verified)");
                ux.progress.detail(format!("   agent: {} (present, sha256 verified)", cached.display()));
                return Ok((cached, build_hash));
            }
            // corrupt entry or missing/stale sidecar: rebuild it.
            _ => {
                let _ = std::fs::remove_file(&cached);
                let _ = std::fs::remove_file(&sidecar);
            }
        }
    }

    std::fs::create_dir_all(&agent_dir)?;
    let src_guard = ScratchDir::new()?;
    let src = src_guard.path().join("src");
    materialize_agent_src(&src)?;
    ux.progress.relabel("guest agent · compiling (musl, first run)");
    // Build to a temp name, then publish binary + sidecar — concurrent bakes
    // may race on the same key, and a reader must never see a half-written file.
    let tmp = agent_dir.join(format!(".tmp-{}-{}", std::process::id(), now_nanos()));
    let log = cache_dir.join("diagnostics").join("agent-build.log");
    build_agent(&src, &tmp, &log, ux)?;
    let sha = sha256_file_hex(&tmp)?;
    std::fs::rename(&tmp, &cached)?;
    std::fs::write(&sidecar, format!("{sha}\n"))?;
    ux.progress.relabel("guest agent");
    ux.progress.note("compiled (musl)");
    ux.progress.detail(format!("   agent: compiled from embedded source (sha256 {sha})"));
    Ok((cached, build_hash))
}

/// Build the guest `tdvmm-agent` as a static, reproducible `x86_64-unknown-linux-
/// musl` binary INSIDE the pinned builder container (Fable §2), from the
/// materialized embedded source at `src_dir` — mounted at /src, the same path
/// the checkout used to mount, so the `--remap-path-prefix` (and therefore the
/// bytes) are unchanged. Determinism knobs: the `agent-release` profile
/// (opt-level=z, lto, codegen-units=1, panic=abort, strip=symbols);
/// `SOURCE_DATE_EPOCH`; the path remaps; `--build-id=none`; and `rust-lld` +
/// self-contained linking so no external C toolchain is pulled. Returns the
/// embedded build hash.
fn build_agent(
    src_dir: &Path,
    out: &Path,
    log: &Path,
    ux: &Ux,
) -> Result<String, Box<dyn std::error::Error>> {
    let (image, digest) = agent_builder_pin()?;
    let img_ref = format!("{image}@{digest}");
    let build_hash = agent_src_id();
    ux.progress.detail(format!("building tdvmm-agent (static musl, reproducible) in {img_ref}"));

    let confdir = ScratchDir::new()?;
    let conf = confdir.path().join("containers.conf");
    std::fs::write(&conf, "[engine]\nruntime=\"runc\"\n")?;
    let work_guard = ScratchDir::new()?;
    let work = work_guard.path();

    run_build(engine::command()
        .env("CONTAINERS_CONF", &conf)
        .arg("run")
        .arg("--rm")
        .arg("-v")
        .arg(format!("{}:/src:ro", src_dir.display()))
        .arg("-v")
        .arg(format!("{}:/work", work.display()))
        .arg("-e")
        .arg(format!("SOURCE_DATE_EPOCH={BUILD_EPOCH}"))
        .arg("-e")
        .arg("CARGO_HOME=/work/cargo")
        .arg("-e")
        .arg("CARGO_TARGET_DIR=/work/target")
        .arg("-e")
        .arg(format!("RUSTFLAGS={AGENT_RUSTFLAGS}"))
        .arg("-e")
        .arg(format!("TDVMM_AGENT_BUILD={build_hash}"))
        .arg(&img_ref)
        .args(["sh", "-c", AGENT_BUILD_SCRIPT]), ux, log)?;

    std::fs::copy(work.join("tdvmm-agent"), out)
        .map_err(|e| format!("agent build produced no binary: {e}"))?;
    Ok(build_hash)
}

/// `tdvmm build-agent -o <path>`: build the reproducible musl agent standalone
/// from the EMBEDDED source — always a fresh container build, never a cache
/// read (the size + double-build byte-identity gate scripts rely on that).
/// Prints `<sha256>  <path>` to stdout. Shares `build_agent()` with `tdvmm
/// build`'s pipeline, but ALWAYS with progress UI disabled / output inherited
/// (scope lock — progress is `build`-only).
pub fn cmd_build_agent(args: BuildAgentArgs) -> Result<i32, Box<dyn std::error::Error>> {
    let outp = PathBuf::from(&args.out);
    if let Some(parent) = outp.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)?;
        }
    }
    let progress = ui::Progress::disabled();
    let ux = Ux::inherit(&progress);
    let src_guard = ScratchDir::new()?;
    let src = src_guard.path().join("src");
    materialize_agent_src(&src)?;
    // Progress is disabled here, so run_build inherits and never writes the
    // log — the path is just the would-be destination.
    let log = resolve_cache_dir(None).0.join("diagnostics").join("agent-build.log");
    let build_hash = build_agent(&src, &outp, &log, &ux)?;
    let sha = sha256_file_hex(&outp)?;
    let size = std::fs::metadata(&outp)?.len();
    eprintln!("   tdvmm-agent: {size} bytes  build={build_hash}  sha256={sha}");
    println!("{sha}  {}", outp.display());
    Ok(0)
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;
    use super::super::fsops::{tree_hash, walk_files};

    /// The embedded set must stay EXACTLY the set `agent_src_id` has always
    /// hashed — identity value and file list, both directions — or the agent's
    /// build hash (compiled into its bytes) drifts and the `.tdvmm` golden
    /// moves. Catches a generator mistake (e.g. a new source file skipped) the
    /// moment it happens; run from a checkout.
    #[test]
    fn embedded_agent_source_matches_checkout() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        let a = tree_hash(&root.join("tdvmm-agent"), &["agent.lock"]).unwrap();
        let p = tree_hash(&root.join("tdvmm-proto"), &[]).unwrap();
        let lock = sha256_file_hex(&root.join("Cargo.lock")).unwrap();
        let checkout_id =
            artifact::sha256_hex(format!("{a}\n{p}\n{lock}\n").as_bytes())[..16].to_string();
        assert_eq!(agent_src_id(), checkout_id, "embedded agent_src_id != checkout construction");

        let mut checkout: BTreeSet<String> = BTreeSet::new();
        checkout.insert("Cargo.lock".to_string());
        for tree in ["tdvmm-agent", "tdvmm-proto"] {
            for f in walk_files(&root.join(tree)).unwrap() {
                if f.file_name().is_some_and(|n| n == "agent.lock") {
                    continue; // generator parity: a stale pre-pivot file is skipped
                }
                checkout.insert(f.strip_prefix(root).unwrap().to_string_lossy().into_owned());
            }
        }
        let embedded: BTreeSet<String> = AGENT_SRC.iter().map(|(p, _)| p.to_string()).collect();
        assert_eq!(embedded, checkout, "embedded file set != checkout file set (stale build?)");
    }

    /// `embedded_tree_hash` relies on the generated table being relpath-sorted.
    #[test]
    fn embedded_table_is_sorted() {
        assert!(AGENT_SRC.windows(2).all(|w| w[0].0 < w[1].0), "AGENT_SRC not strictly sorted");
    }

    /// The embedded root manifest must be the checkout's, verbatim — it
    /// carries the agent's build profile.
    #[test]
    fn embedded_root_manifest_matches_checkout() {
        let on_disk =
            std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml")).unwrap();
        assert_eq!(ROOT_MANIFEST, on_disk);
    }
}
